import { useState, useEffect, useRef } from "react";

const S_STATE = "shdm_low_state";
const S_LOG   = "shdm_low_log";

const COLLECTION_ITEMS = [
  { key: "homeSensors",      label: "Home Sensors"      },
  { key: "behaviorPatterns", label: "Behavior Patterns" },
  { key: "purchaseHistory",  label: "Purchase History"  },
];
const USAGE_ITEMS = [
  { key: "foodServices",     label: "Food Services"     },
  { key: "homeServices",     label: "Home Services"     },
  { key: "wellnessServices", label: "Wellness Services" },
];
const OFFERS = [
  { id: 1, name: "Pizza Meal",     price: 24.99 },
  { id: 2, name: "Burger Combo",   price: 18.99 },
  { id: 3, name: "Chinese Dinner", price: 32.99 },
  { id: 4, name: "Pasta Bowl",     price: 16.99 },
];
const initPrivacy = () => ({
  collection: { homeSensors: null, behaviorPatterns: null, purchaseHistory: null },
  usage:      { foodServices: null, homeServices: null, wellnessServices: null },
});

function makeLogger(setLog) {
  const t0 = Date.now();
  function push(e) {
    const entry = { ...e, timestamp: Date.now(), elapsed_ms: Date.now() - t0 };
    setLog(prev => {
      const next = [...prev, entry];
      try { localStorage.setItem(S_LOG, JSON.stringify(next)); } catch(_) {}
      return next;
    });
  }
  return {
    pageEnter:    (page)              => push({ event: "page_enter",    page }),
    pageExit:     (page, ms)          => push({ event: "page_exit",     page, time_on_page_ms: ms }),
    click:        (el, ctx={})        => push({ event: "click",         element: el, ...ctx }),
    toggle:       (item, val, ctx={}) => push({ event: "toggle",        item, value: val, ...ctx }),
    tabSwitch:    (from, to)          => push({ event: "tab_switch",    from, to }),
    taskComplete: (task)              => push({ event: "task_complete", task }),
    orderPlaced:  (offer)             => push({ event: "order_placed",  offer }),
  };
}

function usePageTimer(name, logger) {
  const t = useRef(Date.now());
  useEffect(() => {
    t.current = Date.now();
    logger.pageEnter(name);
    return () => logger.pageExit(name, Date.now() - t.current);
  }, [name]); // eslint-disable-line
}

const CSS = `
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  :root {
    --bg: #f5f6fa; --surface: #fff; --border: #e4e6ef;
    --text: #111827; --text2: #6b7280; --text3: #9ca3af;
    --blue: #4263eb; --blue-dark: #3451c7; --blue-bg: #eef1ff;
    --green: #16a34a; --green-bg: #dcfce7; --green-bd: #86efac;
    --red: #dc2626; --red-bg: #fee2e2; --red-bd: #fca5a5;
    --r: 12px; --sh: 0 1px 3px rgba(0,0,0,.07), 0 4px 12px rgba(0,0,0,.05);
  }
  body { font-family: 'Inter', sans-serif; background: var(--bg); color: var(--text); min-height: 100vh; }
  .topbar { background: var(--surface); border-bottom: 1px solid var(--border); padding: 10px 16px; display: flex; align-items: center; justify-content: space-between; position: sticky; top: 0; z-index: 50; }
  .topbar-title { font-size: 13px; font-weight: 600; color: var(--text2); }
  .topbar-badge { font-size: 11px; font-weight: 700; color: var(--blue); background: var(--blue-bg); padding: 2px 9px; border-radius: 20px; }
  .wrap { max-width: 560px; margin: 0 auto; padding: 0 16px 90px; }
  .home-hero { text-align: center; padding: 40px 0 28px; }
  .home-icon { width: 68px; height: 68px; border-radius: 50%; background: var(--blue-bg); display: flex; align-items: center; justify-content: center; font-size: 28px; margin: 0 auto 16px; }
  .home-title { font-size: 26px; font-weight: 700; margin-bottom: 4px; }
  .home-sub { font-size: 14px; color: var(--text2); }
  .stats { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-top: 12px; }
  .stat { background: var(--surface); border: 1px solid var(--border); border-radius: var(--r); padding: 14px 18px; box-shadow: var(--sh); }
  .stat-lbl { font-size: 12px; color: var(--text2); margin-bottom: 4px; }
  .stat-val { font-size: 20px; font-weight: 700; }
  .card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--r); box-shadow: var(--sh); overflow: hidden; margin-top: 12px; }
  .card-head { padding: 16px 20px 12px; }
  .card-head-title { font-size: 15px; font-weight: 600; margin-bottom: 3px; }
  .card-head-sub { font-size: 13px; color: var(--text2); }
  .card-row { display: flex; align-items: center; justify-content: space-between; padding: 14px 20px; border-top: 1px solid var(--border); cursor: pointer; transition: background .12s; user-select: none; }
  .card-row:hover { background: var(--bg); }
  .card-row-lbl { font-size: 14px; font-weight: 500; }
  .card-row-arrow { font-size: 16px; color: var(--text3); }
  .back { display: inline-flex; align-items: center; gap: 5px; font-size: 13px; color: var(--text2); cursor: pointer; margin-bottom: 20px; padding: 4px 0; transition: color .12s; }
  .back:hover { color: var(--blue); }
  .page-wrap { padding-top: 24px; }
  .priv-head { margin-bottom: 20px; }
  .priv-head h2 { font-size: 22px; font-weight: 700; margin-bottom: 2px; }
  .priv-head p { font-size: 13px; color: var(--text2); }
  .tabs { display: flex; border-bottom: 2px solid var(--border); margin-bottom: 20px; }
  .tab { flex: 1; display: flex; align-items: center; justify-content: center; gap: 6px; padding: 11px 8px; font-size: 14px; font-weight: 500; color: var(--text2); cursor: pointer; border-bottom: 2px solid transparent; margin-bottom: -2px; transition: color .12s, border-color .12s; user-select: none; }
  .tab.active { color: var(--blue); border-bottom-color: var(--blue); }
  .priv-items { background: var(--surface); border: 1px solid var(--border); border-radius: var(--r); box-shadow: var(--sh); }
  .priv-item { display: flex; align-items: center; justify-content: space-between; padding: 16px 20px; border-bottom: 1px solid var(--border); }
  .priv-item:last-child { border-bottom: none; }
  .priv-item-lbl { font-size: 14px; font-weight: 500; }
  .da { display: flex; gap: 6px; }
  .da-btn { padding: 6px 14px; border-radius: 7px; border: 1.5px solid var(--border); background: var(--surface); font-size: 13px; font-weight: 500; cursor: pointer; transition: background .12s, border-color .12s, color .12s; font-family: inherit; color: var(--text2); }
  .da-deny.on  { background: var(--red-bg);   border-color: var(--red-bd);   color: var(--red);   }
  .da-allow.on { background: var(--green-bg); border-color: var(--green-bd); color: var(--green); }
  .da-deny:hover:not(.on)  { background: var(--red-bg);   border-color: var(--red-bd); }
  .da-allow:hover:not(.on) { background: var(--green-bg); border-color: var(--green-bd); }
  .save-row { display: flex; align-items: center; justify-content: flex-end; padding: 14px 20px; border-top: 1px solid var(--border); background: var(--surface); border-radius: 0 0 var(--r) var(--r); }
  .btn-save { padding: 8px 20px; background: var(--blue); color: #fff; border: none; border-radius: 7px; font-size: 14px; font-weight: 600; cursor: pointer; transition: background .12s; font-family: inherit; }
  .btn-save.saved { background: var(--green); }
  .btn-save:hover:not(.saved) { background: var(--blue-dark); }
  .btn-done { display: block; width: 100%; padding: 15px; background: #16a34a; color: #fff; border: none; border-radius: 10px; font-size: 15px; font-weight: 600; cursor: pointer; margin-top: 12px; transition: background .12s; font-family: inherit; text-align: center; }
  .btn-done:hover { background: #15803d; }
  .off-tabs { display: flex; border-bottom: 2px solid var(--border); margin-bottom: 20px; }
  .off-tab { flex: 1; text-align: center; padding: 11px 8px; font-size: 14px; font-weight: 500; color: var(--text2); cursor: pointer; border-bottom: 2px solid transparent; margin-bottom: -2px; transition: color .12s, border-color .12s; user-select: none; }
  .off-tab.active { color: var(--blue); border-bottom-color: var(--blue); }
  .off-head { font-size: 18px; font-weight: 700; margin-bottom: 16px; }
  .off-list { background: var(--surface); border: 1px solid var(--border); border-radius: var(--r); box-shadow: var(--sh); overflow: hidden; }
  .off-row { display: flex; align-items: center; justify-content: space-between; padding: 16px 20px; border-bottom: 1px solid var(--border); cursor: pointer; transition: background .12s; }
  .off-row:last-child { border-bottom: none; }
  .off-row:hover { background: var(--bg); }
  .off-row-name { font-size: 14px; font-weight: 500; }
  .off-row-price { font-size: 15px; font-weight: 700; color: var(--blue); }
  .no-off { font-size: 14px; color: var(--text2); padding: 20px 0; }
  .order-card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--r); box-shadow: var(--sh); overflow: hidden; margin-bottom: 12px; }
  .order-title { font-size: 17px; font-weight: 700; padding: 18px 20px 14px; border-bottom: 1px solid var(--border); }
  .order-line { display: flex; justify-content: space-between; align-items: center; padding: 13px 20px; border-bottom: 1px solid var(--border); font-size: 14px; }
  .order-line:last-child { border-bottom: none; }
  .order-line.total { font-weight: 700; font-size: 15px; }
  .order-line .val { color: var(--text); }
  .btn-place { display: block; width: 100%; padding: 15px; background: var(--blue); color: #fff; border: none; border-radius: 10px; font-size: 15px; font-weight: 600; cursor: pointer; transition: background .12s; font-family: inherit; }
  .btn-place:hover { background: var(--blue-dark); }
  .confirm-wrap { display: flex; align-items: center; justify-content: center; min-height: 60vh; }
  .confirm-box { background: var(--surface); border: 1px solid var(--border); border-radius: var(--r); box-shadow: var(--sh); padding: 40px 32px; text-align: center; max-width: 380px; width: 100%; }
  .confirm-icon { width: 56px; height: 56px; border-radius: 50%; background: var(--green-bg); border: 2px solid var(--green-bd); display: flex; align-items: center; justify-content: center; margin: 0 auto 16px; font-size: 26px; color: var(--green); }
  .confirm-title { font-size: 20px; font-weight: 700; margin-bottom: 8px; }
  .confirm-sub { font-size: 14px; color: var(--text2); margin-bottom: 24px; }
  .btn-backhome { padding: 11px 24px; background: var(--blue); color: #fff; border: none; border-radius: 8px; font-size: 14px; font-weight: 600; cursor: pointer; transition: background .12s; font-family: inherit; }
  .btn-backhome:hover { background: var(--blue-dark); }
  .logpanel { position: fixed; bottom: 0; left: 0; right: 0; background: #0f1117; color: #c9d1f0; border-top: 1px solid #1e2235; z-index: 100; }
  .lp-bar { display: flex; align-items: center; justify-content: space-between; padding: 8px 14px; cursor: pointer; }
  .lp-bar-l { display: flex; align-items: center; gap: 8px; font-size: 12px; font-family: monospace; color: #6b7db3; }
  .lp-count { font-size: 11px; font-weight: 700; background: var(--blue); color: #fff; padding: 1px 7px; border-radius: 20px; }
  .lp-body { max-height: 200px; overflow-y: auto; }
  .lp-row { display: grid; grid-template-columns: 52px 130px 1fr; gap: 8px; padding: 3px 14px; border-bottom: 1px solid #1e2235; font-size: 11px; font-family: monospace; }
  .lp-t  { color: #4a5275; }
  .lp-ev { color: #818cf8; }
  .lp-d  { color: #93c5fd; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .lp-foot { display: flex; gap: 8px; padding: 6px 14px; border-top: 1px solid #1e2235; }
  .lp-btn { font-size: 11px; padding: 4px 10px; background: transparent; border: 1px solid #2a3050; color: #818cf8; border-radius: 6px; cursor: pointer; font-family: monospace; }
  .lp-btn:hover { background: #1e2235; }
`;

function DA({ value, onDeny, onAllow }) {
  return (
    <div className="da">
      <button className={`da-btn da-deny${value === "deny"  ? " on" : ""}`} onClick={onDeny}>Deny</button>
      <button className={`da-btn da-allow${value === "allow" ? " on" : ""}`} onClick={onAllow}>Allow</button>
    </div>
  );
}

function HomeScreen({ logger, onPrivacy }) {
  usePageTimer("home", logger);
  const now  = new Date();
  const day  = now.toLocaleDateString("en-US", { weekday: "long" });
  const time = now.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" });
  return (
    <div style={{ paddingTop: 32 }}>
      <div className="home-hero">
        <div className="home-icon">🏠</div>
        <div className="home-title">Welcome Home</div>
        <div className="home-sub">{day}, {time}</div>
      </div>
      <div className="card">
        <div className="card-head">
          <div className="card-head-title">Your Smart Home</div>
          <div className="card-head-sub">Manage your home automation and privacy settings</div>
        </div>
        <div className="card-row" onClick={() => { logger.click("privacy_settings"); onPrivacy(); }}>
          <span className="card-row-lbl">Privacy Settings</span>
          <span className="card-row-arrow">→</span>
        </div>
      </div>
      <div className="stats">
        <div className="stat"><div className="stat-lbl">Temperature</div><div className="stat-val">72°F</div></div>
        <div className="stat"><div className="stat-lbl">People Home</div><div className="stat-val">2</div></div>
      </div>
    </div>
  );
}

function PrivacyScreen({ privacy, onSave, logger, onBack, onDone }) {
  usePageTimer("privacy_settings", logger);
  const [tab,   setTab]   = useState("collection");
  const [col,   setCol]   = useState({ ...privacy.collection });
  const [usg,   setUsg]   = useState({ ...privacy.usage });
  const [saved, setSaved] = useState(false);

  function toggleCol(key, val) {
    const next = col[key] === val ? null : val;
    logger.toggle(key, next, { tab: "collection" });
    setCol(c => ({ ...c, [key]: next }));
    setSaved(false);
  }
  function toggleUsg(key, val) {
    const next = usg[key] === val ? null : val;
    logger.toggle(key, next, { tab: "usage" });
    setUsg(u => ({ ...u, [key]: next }));
    setSaved(false);
  }
  function handleSave() {
    logger.click("save_my_choices");
    logger.taskComplete("privacy_settings_saved");
    onSave({ collection: col, usage: usg });
    setSaved(true);
  }
  function handleTabSwitch(t) {
    logger.tabSwitch(tab, t);
    setTab(t);
  }

  return (
    <div className="page-wrap">
      <div className="back" onClick={() => { logger.click("back_to_home", { from: "privacy" }); onBack(); }}>← Back to Home</div>
      <div className="priv-head">
        <h2>Privacy Settings</h2>
        <p>Control your data</p>
      </div>
      <div className="tabs">
        <div className={`tab${tab === "collection" ? " active" : ""}`} onClick={() => handleTabSwitch("collection")}>🗄️ Data Collection</div>
        <div className={`tab${tab === "usage"      ? " active" : ""}`} onClick={() => handleTabSwitch("usage")}>⚙️ Data Usage</div>
      </div>
      {tab === "collection" && (
        <>
          <div className="priv-items">
            {COLLECTION_ITEMS.map(it => (
              <div className="priv-item" key={it.key}>
                <span className="priv-item-lbl">{it.label}</span>
                <DA value={col[it.key]} onDeny={() => toggleCol(it.key, "deny")} onAllow={() => toggleCol(it.key, "allow")} />
              </div>
            ))}
          </div>
          <div className="save-row">
            <button className={`btn-save${saved ? " saved" : ""}`} onClick={handleSave}>
              {saved ? "Saved!" : "Save My Choices"}
            </button>
          </div>
        </>
      )}
      {tab === "usage" && (
        <>
          <div className="priv-items">
            {USAGE_ITEMS.map(it => (
              <div className="priv-item" key={it.key}>
                <span className="priv-item-lbl">{it.label}</span>
                <DA value={usg[it.key]} onDeny={() => toggleUsg(it.key, "deny")} onAllow={() => toggleUsg(it.key, "allow")} />
              </div>
            ))}
          </div>
          <div className="save-row">
            <button className={`btn-save${saved ? " saved" : ""}`} onClick={handleSave}>
              {saved ? "Saved!" : "Save My Choices"}
            </button>
          </div>
        </>
      )}
      <button className="btn-done" onClick={() => { logger.click("done_return_to_home"); onDone(); }}>
        Done – Return to Home
      </button>
    </div>
  );
}

function OffersScreen({ logger, onSelect, onHome }) {
  usePageTimer("offers", logger);
  const [tab, setTab] = useState("food");
  return (
    <div className="page-wrap">
      <div className="back" onClick={() => { logger.click("back_to_home", { from: "offers" }); onHome(); }}>← Back to Home</div>
      <div className="off-tabs">
        {["food", "home", "wellness"].map(t => (
          <div key={t} className={`off-tab${tab === t ? " active" : ""}`}
            onClick={() => { logger.tabSwitch(tab, t); setTab(t); }}>
            {t.charAt(0).toUpperCase() + t.slice(1)}
          </div>
        ))}
      </div>
      {tab === "food" ? (
        <>
          <div className="off-head">Available Offers</div>
          <div className="off-list">
            {OFFERS.map(o => (
              <div className="off-row" key={o.id}
                onClick={() => { logger.click("select_offer", { offer: o.name, price: o.price }); onSelect(o); }}>
                <span className="off-row-name">{o.name}</span>
                <span className="off-row-price">${o.price.toFixed(2)}</span>
              </div>
            ))}
          </div>
        </>
      ) : (
        <div className="no-off">No offers available for this category.</div>
      )}
    </div>
  );
}

function OrderScreen({ offer, logger, onPlace, onBack }) {
  usePageTimer("order_summary", logger);
  return (
    <div className="page-wrap">
      <div className="back" onClick={() => { logger.click("back_to_offers"); onBack(); }}>← Back</div>
      <div className="order-card">
        <div className="order-title">Order Summary</div>
        <div className="order-line">
          <span>Item</span><span className="val" style={{ fontWeight: 600 }}>{offer.name}</span>
        </div>
        <div className="order-line">
          <span>Delivery</span><span className="val">Standard</span>
        </div>
        <div className="order-line total">
          <span>Total</span><span className="val">${offer.price.toFixed(2)}</span>
        </div>
      </div>
      <button className="btn-place" onClick={() => {
        logger.click("place_order", { offer: offer.name });
        logger.orderPlaced(offer.name);
        logger.taskComplete("order_placed");
        onPlace();
      }}>Place Order</button>
    </div>
  );
}

function ConfirmScreen({ logger, onHome }) {
  usePageTimer("order_confirmation", logger);
  return (
    <div className="confirm-wrap">
      <div className="confirm-box">
        <div className="confirm-icon">✓</div>
        <div className="confirm-title">Order Placed</div>
        <div className="confirm-sub">Your order has been confirmed</div>
        <button className="btn-backhome" onClick={() => { logger.click("back_to_home", { from: "confirmation" }); onHome(); }}>
          Back to Home
        </button>
      </div>
    </div>
  );
}

function LogPanel({ log }) {
  const [open, setOpen] = useState(false);
  const bodyRef = useRef(null);
  useEffect(() => {
    if (open && bodyRef.current) bodyRef.current.scrollTop = bodyRef.current.scrollHeight;
  }, [log, open]);
  const t0 = log[0]?.timestamp ?? Date.now();
  function download(content, name) {
    const a = document.createElement("a");
    a.href = URL.createObjectURL(new Blob([content], { type: "text/plain" }));
    a.download = name;
    a.click();
  }
  function toCSV() {
    const keys = ["event","timestamp","elapsed_ms","page","element","item","value","task","offer","from","to","time_on_page_ms"];
    const rows = [keys.join(",")];
    log.forEach(e => rows.push(keys.map(k => {
      const v = e[k];
      if (v == null) return "";
      const s = String(v);
      return s.includes(",") ? `"${s}"` : s;
    }).join(",")));
    return rows.join("\n");
  }
  return (
    <div className="logpanel">
      <div className="lp-bar" onClick={() => setOpen(o => !o)}>
        <div className="lp-bar-l">
          <span>⬛ Interaction Log</span>
          <span className="lp-count">{log.length}</span>
        </div>
        <span style={{ fontSize: 11, color: "#4a5275" }}>{open ? "▾ einklappen" : "▴ ausklappen"}</span>
      </div>
      {open && (
        <>
          <div className="lp-body" ref={bodyRef}>
            {log.map((e, i) => {
              const sec = ((e.timestamp - t0) / 1000).toFixed(1);
              const detail = [
                e.page    && `page=${e.page}`,
                e.element && `el=${e.element}`,
                e.item    && `item=${e.item}`,
                e.value   != null && `val=${e.value}`,
                e.task    && `task=${e.task}`,
                e.offer   && `offer=${e.offer}`,
                e.from    && `${e.from}→${e.to}`,
                e.time_on_page_ms && `spent=${e.time_on_page_ms}ms`,
              ].filter(Boolean).join("  ");
              return (
                <div className="lp-row" key={i}>
                  <span className="lp-t">{sec}s</span>
                  <span className="lp-ev">{e.event}</span>
                  <span className="lp-d">{detail}</span>
                </div>
              );
            })}
          </div>
          <div className="lp-foot">
            <button className="lp-btn" onClick={() => download(toCSV(), `shdm_low_${Date.now()}.csv`)}>⬇ CSV</button>
            <button className="lp-btn" onClick={() => download(JSON.stringify(log, null, 2), `shdm_low_${Date.now()}.json`)}>⬇ JSON</button>
            <button className="lp-btn" onClick={() => { localStorage.removeItem(S_LOG); window.location.reload(); }}>Clear</button>
          </div>
        </>
      )}
    </div>
  );
}

export default function App() {
  const [privacy, setPrivacy] = useState(() => {
    try { const s = localStorage.getItem(S_STATE); if (s) return JSON.parse(s); } catch(_) {}
    return initPrivacy();
  });
  const [log, setLog] = useState(() => {
    try { const s = localStorage.getItem(S_LOG); if (s) return JSON.parse(s); } catch(_) {}
    return [];
  });
  const logger = useRef(makeLogger(setLog)).current;
  const [screen, setScreen] = useState("home");
  const [offer,  setOffer]  = useState(null);

  function savePrivacy(updated) {
    setPrivacy(updated);
    try { localStorage.setItem(S_STATE, JSON.stringify(updated)); } catch(_) {}
  }

  return (
    <>
      <style>{CSS}</style>
      <div className="topbar">
        <span className="topbar-title">SHDM Usability Study</span>
        <span className="topbar-badge">Low Flow</span>
      </div>
      <div className="wrap">
        {screen === "home"    && <HomeScreen    logger={logger} onPrivacy={() => setScreen("privacy")} />}
        {screen === "privacy" && <PrivacyScreen privacy={privacy} onSave={savePrivacy} logger={logger} onBack={() => setScreen("home")} onDone={() => setScreen("offers")} />}
        {screen === "offers"  && <OffersScreen  logger={logger} onSelect={o => { setOffer(o); setScreen("order"); }} onHome={() => setScreen("home")} />}
        {screen === "order"   && <OrderScreen   offer={offer} logger={logger} onPlace={() => setScreen("confirm")} onBack={() => setScreen("offers")} />}
        {screen === "confirm" && <ConfirmScreen logger={logger} onHome={() => setScreen("home")} />}
      </div>
      <LogPanel log={log} />
    </>
  );
}
